import { NextRequest, NextResponse } from 'next/server';
import { AppState, catById, compute, peso, pesoR, shortDate } from '@/lib/budget';

interface AdviceRequest {
  state: AppState;
  history: { role: 'user' | 'assistant'; text: string }[];
  message: string;
}

const OLLAMA_HOST = process.env.OLLAMA_HOST || 'http://localhost:11434';
const OLLAMA_MODEL = process.env.OLLAMA_MODEL;

const CAT_TIPS: Record<string, string> = {
  food: 'Magbaon ng lunch 2-3x a week, o mag-share ng ulam sa tropa. Iwas milk tea araw-araw.',
  transpo: 'Sumabay sa classmates pauwi, maglakad kung malapit lang, at iwas Grab/Angkas kung may jeep.',
  school: 'Mag-photocopy na lang ng hiram na libro, i-print lang ang talagang kailangan, at bumili ng supplies nang maramihan.',
  load: 'Mag-piso WiFi o school WiFi, at pumili ng mas mahabang promo kaysa daily na load.',
  gala: 'Mag-set ng gala budget per week, at hanapin ang libreng gala tulad ng park o tambay sa bahay.',
  other: 'I-review ang "Others" mo. Baka may maliliit na gastos na pwedeng iwasan.',
};

function summarize(state: AppState) {
  const c = compute(state);
  const cats = c.byCat.map(x => `${x.label} ${pesoR(x.sum)} (${Math.round((x.sum / Math.max(1, c.spent)) * 100)}%)`).join(', ');
  return {
    c,
    text: [
      `Allowance: ${pesoR(state.budget)} from ${shortDate(state.start)} to ${shortDate(state.end)} (${c.total} days).`,
      `Day ${c.elapsed} of ${c.total}, ${c.left} days left.`,
      `Spent: ${pesoR(c.spent)} (${Math.round(c.pct)}%). Remaining: ${c.remaining < 0 ? '-' : ''}${pesoR(c.remaining)}.`,
      `Average spend per day: ${pesoR(c.avgPerDay)}. Safe spend per day from now: ${pesoR(c.perDay)}.`,
      `By category: ${cats || 'none yet'}.`,
    ].join('\n'),
  };
}

async function askOllama(context: string, history: AdviceRequest['history'], message: string) {
  if (!OLLAMA_MODEL) return null;
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 45000);
  try {
    const res = await fetch(`${OLLAMA_HOST}/api/chat`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      signal: ctrl.signal,
      body: JSON.stringify({
        model: OLLAMA_MODEL,
        stream: false,
        messages: [
          {
            role: 'system',
            content:
              'You are Tats, a friendly budget buddy for a Filipino college student. Reply in casual Taglish, ' +
              'short (2-5 sentences or a few bullet points), practical, and grounded in the numbers below. ' +
              'Use ₱ for money. Answer the question directly first. Never invent expenses or numbers that are not listed.\n\nStudent budget data:\n' + context,
          },
          ...history.slice(-8).map(m => ({ role: m.role, content: m.text })),
          { role: 'user', content: message },
        ],
      }),
    });
    if (!res.ok) return null;
    const data = await res.json();
    return (data?.message?.content as string)?.trim() || null;
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

function ruleReply(state: AppState, message: string) {
  const { c } = summarize(state);
  const m = message.toLowerCase();
  const top = c.byCat[0];
  const amount = Number((m.match(/\d+(\.\d+)?/) || [])[0]) || 0;

  if (amount > 0 && /(bili|bilhin|buy|afford|kaya|gastos ng|worth)/.test(m)) {
    const after = c.remaining - amount;
    const perDayAfter = after > 0 && c.left > 0 ? after / c.left : 0;
    if (after < 0) return `Hindi kaya ngayon. Kulang ka ng ${peso(-after)}. Hintayin muna ang next allowance o mag-ipon nang paunti-unti.`;
    return `Kung bibilhin mo yan (${peso(amount)}), matitira ${peso(after)}. Bababa ang safe gastos mo from ${pesoR(c.perDay)} to ${pesoR(perDayAfter)} per day. ${perDayAfter < c.avgPerDay * 0.7 ? 'Medyo hihigpit, pag-isipan muna.' : 'Kaya pa naman!'}`;
  }

  if (/(ipon|save|savings|tipid|matira)/.test(m)) {
    const target = Math.max(0, Math.round(c.remaining * 0.2));
    const perDay = c.left > 0 ? (c.remaining - target) / c.left : 0;
    return `Try mo mag-target ng ${pesoR(target)} ipon (20% ng natitira). Para makuha yan, gastos ka lang ng ${pesoR(perDay)}/day.${top ? ` Pinakamadaling bawasan: ${top.label}. ${CAT_TIPS[top.id]}` : ''}`;
  }

  if (/(saan|where|category|pinakamalaki|top|breakdown)/.test(m)) {
    if (!c.byCat.length) return 'Wala ka pang gastos this period, kaya wala pang breakdown.';
    return 'Breakdown ng gastos mo:\n' + c.byCat.map(x => `• ${x.label}: ${pesoR(x.sum)} (${Math.round((x.sum / c.spent) * 100)}%)`).join('\n');
  }

  for (const [id, tip] of Object.entries(CAT_TIPS)) {
    const label = catById(id).label.toLowerCase();
    if (m.includes(id) || m.includes(label.split(' ')[0])) return `Tips para sa ${catById(id).label}: ${tip}`;
  }

  if (/(tip|bawas|cut|paano|how|advice|payo)/.test(m)) {
    if (!top) return 'Wala pang data. Mag-log ka muna ng ilang gastos para makapagbigay ako ng specific na tips.';
    return `Pinakamalaki mong gastos ay ${top.label} (${pesoR(top.sum)}). ${CAT_TIPS[top.id]} Kung mabawasan mo ito ng 30%, makakatipid ka ng ${pesoR(top.sum * 0.3)}.`;
  }

  return `${c.st.title}. Nagastos ka na ng ${pesoR(c.spent)} (${Math.round(c.pct)}%) at ${c.remaining < 0 ? `lampas ka ng ${pesoR(-c.remaining)}` : `may ${pesoR(c.remaining)} pa for ${c.left} days`}. Safe gastos: ${pesoR(c.perDay)}/day.${top ? ` Bantayan ang ${top.label}.` : ''}`;
}

export async function POST(req: NextRequest) {
  try {
    const { state, history = [], message }: AdviceRequest = await req.json();
    if (!message || !state) return NextResponse.json({ error: 'missing input' }, { status: 400 });

    const { text } = summarize(state);
    const fallback = ruleReply(state, message);
    // The rule-based answer gives the model correct math to build on
    const ai = await askOllama(`${text}

Computed analysis for this question (numbers are correct, reuse them):
${fallback}`, history, message);
    if (ai) return NextResponse.json({ reply: ai, source: 'ai' });

    return NextResponse.json({ reply: fallback, source: 'rules' });
  } catch {
    return NextResponse.json({ reply: 'May error, try mo ulit mamaya.', source: 'rules' });
  }
}
